"""# + "\n"
    private func rows(_ wire: String) throws -> [[String:Any]] {
        try wire.split(separator:"\n").map { try JSONSerialization.jsonObject(with:Data($0.utf8)) as! [String:Any] }
    }
    private func bytes(_ rows: [[String:Any]]) throws -> Data {
        var result = Data()
        for row in rows { result.append(try JSONSerialization.data(withJSONObject:row,options:[.sortedKeys])); result.append(10) }
        return result
    }
    private func receipt(_ wire: Data, reference: String, source: Bool = true) throws -> DolbyP81MetadataStream.Receipt {
        let r = try rows(reference), end = r.last!
        let fingerprint = SourceFingerprint(sha256:end["input_sha256"] as! String,byteCount:(end["input_bytes"] as! NSNumber).int64Value)
        let stream = try DolbyP81MetadataStream(source:fingerprint,sourceRole:source)
        for start in stride(from:0,to:wire.count,by:7) { stream.receive(wire.subdata(in:start..<min(start+7,wire.count))) }
        let h = r[0]
        let header = DolbyInspectionHeader(version:3,inputType:"matroska-hevc-packets",parser:h["parser"] as! String,trackNumber:(h["track_number"] as! NSNumber).int64Value,
            declaredPixelWidth:h["declared_pixel_width"] as! Int,declaredPixelHeight:h["declared_pixel_height"] as! Int,
            declaredCropLeftRightTopBottom:h["declared_crop_left_right_top_bottom"] as! [Int],
            declaredDisplayWidthHeight:(h["declared_display_width_height"] as! [Any]).map { $0 as? Int },declaredDisplayUnit:h["declared_display_unit"] as! Int,
            timestampScaleNs:(h["timestamp_scale_ns"] as! NSNumber).int64Value,configurationSha256:h["configuration_sha256"] as! String,configurationBytes:h["configuration_bytes"] as! Int)
        return try stream.finish(status:0,packetSequence:end["packet_sequence_sha256"] as! String,header:header)
    }
    @Test func completeGeneratedWireHasBoundSourceAndExpectedOutputMetadata() throws {
        let source = try receipt(Data(sourceWire.utf8),reference:sourceWire)
        let output = try receipt(Data(outputWire.utf8),reference:outputWire,source:false)
        #expect(source.supported && output.supported && source.records == 8 && output.records == 8)
        #expect(source.expectedOutputMetadataSHA256 == output.expectedOutputMetadataSHA256)
        #expect(source.enhancementNALs == 20 && output.enhancementNALs == 0)
    }
    @Test func malformedOrUnboundWireCannotReturnReceipt() throws {
        let original = try rows(sourceWire)
        for change in ["header-hash","header-track","header-width","source","packet-hash","packet-pts","record-pts","record-index","missing","duplicate","complete","recheck"] {
            var r = original
            switch change {
            case "header-hash": r[0]["configuration_sha256"] = String(repeating:"0",count:64)
            case "header-track": r[0]["track_number"] = 2
            case "header-width": r[0]["declared_pixel_width"] = 3842
            case "source": r[r.count-1]["input_sha256"] = String(repeating:"0",count:64)
            case "packet-hash": r[1]["sha256"] = String(repeating:"0",count:64)
            case "packet-pts": r[1]["pts_ns"] = 1
            case "record-pts": r[2]["pts_ns"] = 1
            case "record-index": r[2]["packet_index"] = 1
            case "missing": r.remove(at:2)
            case "duplicate": r.insert(r[2],at:3)
            case "complete": r.removeLast()
            default: r[r.count-1]["source_recheck"] = false
            }
            #expect(throws:(any Error).self) { _ = try receipt(bytes(r),reference:sourceWire) }
        }
        #expect(throws:(any Error).self) { _ = try receipt(Data(sourceWire.utf8).dropLast(),reference:sourceWire) }
        #expect(throws:(any Error).self) { _ = try receipt(Data((sourceWire+"{}\n").utf8),reference:sourceWire) }
        #expect(throws:(any Error).self) { _ = try CompanionArchiveJSON.metadataObject(Data(#"{"x":0,"x":1}"#.utf8)) }
        #expect(throws:(any Error).self) { _ = try CompanionArchiveJSON.metadataObject(Data(repeating:32,count:65_536)) }
    }
    @Test func unsupportedSourceAndChangedOutputNeverMatchQualifiedReceipt() throws {
        let original = try rows(sourceWire)
        for change in ["matrix","diagonal","boolean","unknown","compressed","CM4","partition","curve","L6"] {
            var r = original, m = r[2]["metadata"] as! [String:Any]
            var dm = m["vdr_dm_data"] as! [String:Any], mapping = m["rpu_data_mapping"] as! [String:Any]
            switch change {
            case "matrix": dm["ycc_to_rgb_coef0"] = 9575
            case "diagonal": dm["source_diagonal"] = 1024
            case "boolean": dm["scene_refresh_flag"] = true
            case "unknown": m["unknown"] = 0
            case "compressed": dm["compressed"] = true
            case "CM4": dm["cmv40_metadata"] = [:] as [String:Int]
            case "partition": mapping["num_x_partitions_minus1"] = 1
            case "curve": mapping["curves"] = [] as [Int]
            default:
                var cm = dm["cmv29_metadata"] as! [String:Any], blocks = cm["ext_metadata_blocks"] as! [[String:Any]]
                var l6 = blocks[2]["Level6"] as! [String:Any]; l6["max_content_light_level"] = 10001
                blocks[2]["Level6"] = l6; cm["ext_metadata_blocks"] = blocks; dm["cmv29_metadata"] = cm
            }
            m["vdr_dm_data"] = dm; m["rpu_data_mapping"] = mapping; r[2]["metadata"] = m
            #expect(try !receipt(bytes(r),reference:sourceWire).supported)
        }
        let expected = try receipt(Data(sourceWire.utf8),reference:sourceWire).expectedOutputMetadataSHA256
        var r = try rows(outputWire), m = r[2]["metadata"] as! [String:Any], dm = m["vdr_dm_data"] as! [String:Any]
        dm["source_diagonal"] = 43; m["vdr_dm_data"] = dm; r[2]["metadata"] = m
        #expect(try receipt(bytes(r),reference:outputWire,source:false).expectedOutputMetadataSHA256 != expected)
    }
    @Test func fullReaderPreservesParserCauseAndSameUncertainRunner() async throws {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("dolby-p81-metadata-" + UUID().uuidString)
        try FileManager.default.createDirectory(at:root,withIntermediateDirectories:false,attributes:[.posixPermissions:0o700])
        print("GENERATED_P81_METADATA_RETAINED \(root.path)")
        let helper = root.appendingPathComponent("helper")
        try Data("#!/bin/sh\nprintf 'malformed\\n'\nexit 7\n".utf8).write(to:helper,options:.withoutOverwriting)
        try FileManager.default.setAttributes([.posixPermissions:0o700],ofItemAtPath:helper.path)
        let report = DolbySourceReport(header:.init(version:3,inputType:"matroska-hevc-packets",parser:"libdovi 3.3.2",trackNumber:1,
            declaredPixelWidth:3840,declaredPixelHeight:2160,declaredCropLeftRightTopBottom:[0,0,0,0],declaredDisplayWidthHeight:[nil,nil],declaredDisplayUnit:0,
            timestampScaleNs:1_000_000,configurationSha256:String(repeating:"0",count:64),configurationBytes:113),
            packets:8,records:8,sceneRefreshes:0,enhancementNALs:20,packetsWithoutRPU:0,packetsWithMultipleRPUs:0,mappings:[:],activeAreas:[:],cmv29Records:8,cmv40Records:0,
            source:.init(sha256:String(repeating:"0",count:64),byteCount:1000),packetSequenceSHA256:String(repeating:"0",count:64),peakTrackedHeap:1)
        weak var retained: ToolRunner?
        do {
            _ = try await ToolRunner.$readerCloseReport.withValue({ _, succeeded in
                #expect(succeeded); return true
            }) { try await DolbyP81Metadata.read(root.appendingPathComponent("unused"),report:report,helper:helper) }
            Issue.record("Expected reader uncertainty before malformed metadata")
        } catch let error as ToolRunner.ReaderCloseFailure {
            #expect(error.roles == ["stderr","stdout"])
            #expect(error.consumerCause is NativeExportError)
            #expect(error.owner.ownedLivePID == nil && error.owner.retainsUncertainty)
            retained = error.owner
        }
        #expect(retained?.retainsUncertainty == true)
    }

